/* Spawn point for the moby: its slot's stored position and rotation, or, with no slot, a point beside it on the side
   facing the hero.
   Adapted from Lombyte's project (GPL-3.0) for PAL by OpenRAC's tools/port.py: src/overlays/shared/gameplay/entities/002a4038.c, FUN_L02_002d8910. */
void compute_tresspasser_pad_camera_transform(float *pos, float *rot, Moby *moby) {
    struct TrespasserPuzzleVars *vars = (struct TrespasserPuzzleVars *)moby->pvars;
    V2d8910 v;
    float left;
    float right;
    float pick;
    float to;
    float dl;
    int idx;
    char *base;

    idx = vars->scene_point_idx;
    if (idx == -1) {
        left = FastAddRots(moby->rot.z, 1.57079637f);
        right = FastAddRots(moby->rot.z, -1.57079637f);
        to = fast_atan2(aridia_player_camera_r.x - moby->pos.x, aridia_player_camera_r.y - moby->pos.y);
        dl = FastDiffRots(to, left);
        pick = dl < FastDiffRots(to, right) ? left : right;
        FastVecAdd(v, hero_pos, &moby->pos);
        FastVecScale(v, v, 0.5f);
        qcopy(pos, v);
        pos[0] += FastCos(pick) * 2.0f;
        pos[1] += FastSin(pick) * 2.0f;
        pos[2] += 1.0f;
        rot[0] = 0;
        rot[1] = 0;
        rot[2] = FastAddRots(pick, 3.14159274f);
    } else {
        base = l02_cuboids;
        qcopy(pos, base + idx * 128 + 0x30);
        qcopy(rot, base + idx * 128 + 0x70);
    }
}
