/* Update for a ship moby: eases its attach point along a path, spawns effects and drives its state machine. */
void background_ship_2_update(char *moby) {
    struct BackgroundShip2Vars *d;
    char *t;
    int r;
    int flag = 0;
    float tv[4];
    float f70;
    float p2;
    float x;
    int r1;
    int r2;
    int r3;
    d = (struct BackgroundShip2Vars *)((Moby *)moby)->pvars;
    t = aridia_paths[d->path];
    r = (int)MobyGetHitMessage(moby, 0x10000, 0);
    switch (((Moby *)moby)->state) {
        case 0: {
            int m1;
            ((Moby *)moby)->update_dist = 0xFF;
            ((Moby *)moby)->draw_dist = 0xFF;
            if (g_current_level_index_r == LEVEL_ORXON) {
                ((Moby *)moby)->scale = ((Moby *)moby)->scale * 0.5f;
            }
            m1 = -1;
            if (d->path == m1) {
                STUB_printf(background_ship_2_no_path_msg, *(short *)&((Moby *)moby)->save_id);
                DeleteMoby(moby);
                return;
            }
            if (*(int *)aridia_paths[d->path] == 0) {
                STUB_printf(background_ship_2_empty_path_msg, *(short *)&((Moby *)moby)->save_id);
                DeleteMoby(moby);
                return;
            }
            f70 = fast_vec_dist(aridia_paths[d->path] + 0x10, aridia_paths[d->path] + 0x20);
            d->unk_2C = 0x28;
            d->first_leg = f70;
            d->unk_2B = 1;
            qcopy(&((Moby *)moby)->pos, aridia_paths[d->path] + 0x10);
            d->phase = random_angle_radians();
            d->voice = m1;
            ((Moby *)moby)->state = 1;
            ((Moby *)moby)->flags |= 0x10;
            d->path_pos = d->start_frac * (float)*(int *)t;
            break;
        }
        case 1:
            if (*(unsigned char *)hero_vehicle_mode == 1 && g_current_level_index_r == LEVEL_ORXON) {
                DeleteMoby(moby);
                return;
            }
            qcopy(tv, &((Moby *)moby)->pos);
            if (voice_is_playing(moby, d->voice) == 0) {
                d->voice = Moby_PlaySound(1, 4, (int)moby);
            }
            p2 = background_ship_2_speed * g_frame_time;
            if (g_current_level_index_r == LEVEL_ORXON) {
                p2 = p2 * 0.25f;
            }
            d->path_pos = d->path_pos + p2 / d->first_leg;
            if ((float)*(int *)t < d->path_pos) {
                d->path_pos = d->path_pos - (float)*(int *)t;
            }
            if ((unsigned int)(g_current_level_index_r - 9) < 2) {
                sample_camera_path((int *)t, 1, &((Moby *)moby)->pos, &((Moby *)moby)->rot.x, 0, d->path_pos);
            } else {
                sample_camera_path((int *)t, 0, &((Moby *)moby)->pos, &((Moby *)moby)->rot.x, 0, d->path_pos);
            }
            if (((Moby *)moby)->pos.x < 8.0f) {
                *(int *)&((Moby *)moby)->collision = 0;
            } else if (((Moby *)moby)->pos.y < 8.0f) {
                *(int *)&((Moby *)moby)->collision = 0;
            } else {
                *(int *)&((Moby *)moby)->collision = *(int *)(*(char **)&((Moby *)moby)->pclass + 0x10);
            }
            if (((Moby *)moby)->visible != 0) {
                if (g_current_level_index_r != LEVEL_ORXON) {
                    spawn_background_ship_2_joint_sparks(moby, tv);
                } else {
                    spawn_background_ship_2_level_10_joint_sparks(moby, tv);
                }
            }
            if (r != 0 && 0.0f < *(float *)(r + 0x2C)) {
                flag = 1;
            }
            if (flag) {
                ((Moby *)moby)->state = 2;
            }
            break;
        case 2:
            if (g_current_level_index_r == LEVEL_ARIDIA) {
                aridia_skill_ship_kills = aridia_skill_ship_kills + 1;
                if (aridia_skill_ship_kills >= 3) {
                    unsigned char *p = gSkillPoints;
                    if (p[2] == 0) {
                        p[2] = 1;
                        allocate_voice_for_bank_entry(1, 0, 0);
                        queue_dialogue_message(0x53DB, -1);
                    }
                }
            }
            if (g_current_level_index_r == LEVEL_GASPAR) {
                if (*(int *)hero_current_state == 0x32) {
                    gaspar_skill_ship_kills = gaspar_skill_ship_kills + 1;
                    if (gaspar_skill_ship_kills >= 5) {
                        unsigned char *p = gSkillPoints;
                        if (p[0xF] == 0) {
                            p[0xF] = 1;
                            allocate_voice_for_bank_entry(1, 0, 0);
                            queue_dialogue_message(0x53DB, -1);
                        }
                    }
                }
            }
            Moby_PlaySound(0, 0, (int)moby);
            FastVecScale(tv, &((Moby *)moby)->rot_row0, background_ship_2_debris_speed * frame_scale);
            tv[2] = tv[2] + background_ship_2_debris_lift * frame_scale;
            r1 = scale_ticks(90);
            SpawnBreakFragment(moby, 0x5F6, &((Moby *)moby)->pos.x, (void *)&((Moby *)moby)->rot, r1, 0,
                               g_frame_time_sq * 12.0f, tv, aridia_zero_vec, aridia_zero_vec);
            r2 = scale_ticks(90);
            SpawnBreakFragment(moby, 0x5F8, &((Moby *)moby)->pos.x, (void *)&((Moby *)moby)->rot, r2, 0,
                               g_frame_time_sq * 12.0f, tv, aridia_zero_vec, aridia_zero_vec);
            r3 = scale_ticks(90);
            SpawnBreakFragment(moby, 0x5F9, &((Moby *)moby)->pos.x, (void *)&((Moby *)moby)->rot, r3, 0,
                               g_frame_time_sq * 12.0f, tv, aridia_zero_vec, aridia_zero_vec);
            DeleteMoby(moby);
            return;
        default:
            break;
    }
    if (((Moby *)moby)->visible != 0) {
        x = FastSin(d->phase) * 4.0f - 3.0f;
        if (1.0f < x) {
            x = 1.0f;
        } else if (x < 0.0f) {
            x = 0.0f;
        }
        {
            int res;
            float k;
            res = FastTweenColor(background_ship_2_light_color_off, background_ship_2_light_color_on, x);
            k = background_ship_2_light_spin_rate * 0.017453292f * g_frame_time;
            ((Moby *)moby)->glow_color = res;
            d->phase = FastAddRots(d->phase, k);
        }
        prepare_background_ship_2_joint_draw_data(moby);
    }
}
