/* Update for a moby that waits for a float flag on a nearby object then runs a delete sequence. */
void white_flower_update(char *m) {
    int hit = 0;
    struct HitMessage *r = (struct HitMessage *)MobyGetHitMessage(m, 0x10000, 0);
    switch (((Moby *)m)->state) {
        case 0:
            ((Moby *)m)->state = 1;
            break;
        case 1:
            if (r != 0 && r->damage > 0.0f)
                hit = 1;
            if (hit)
                ((Moby *)m)->state = 2;
            break;
        case 2:
            Moby_PlaySound(0, 0, (int)m);
            spawn_proximity_gated_bolts(m);
            spawn_moby_break_fragments(m, 0x71D, 1, 0x71D, 1, 5, 2);
            spawn_moby_from_placement(m, 0x71C);
            DeleteMoby(m);
            break;
    }
}

