/* Checks whether the target's direction is within a and b degrees of the reference axis. */
int test_moby_camera_target_angle_limits(char *moby, float a, float b) {
    float d[4];
    float p[4];
    float q[4];
    float r[4];
    char *data;
    char *vec = aridia_player_camera_follow;
    char *g;
    float dot1;
    float dot2;
    float lenq;
    float lenr;
    float dot3;
    float den;

    char *tbl = l02_moby_record_table;
    char *src;

    data = *(char **)(tbl + *(short *)(moby + 0x84) * 32 + 0x1C);
    src = *(char **)(data + 0x48);
    if (a == 0.0f && b == 0.0f) {
        return 1;
    }
    g = aridia_player_camera;
    FastVecSub(d, src + 0x10, *(char **)(g + 0x180) + 0x30);
    dot1 = FastVecDot(d, (vec + 0x30));
    FastVecScale(p, (vec + 0x30), dot1);
    FastVecSub(q, d, p);
    lenq = FastVecLength(q);
    dot2 = FastVecDot(*(char **)(g + 0x180), (vec + 0x30));
    FastVecScale(p, (vec + 0x30), dot2);
    FastVecSub(r, *(char **)(g + 0x180), p);
    lenr = FastVecLength(r);
    if (b != 0.0f) {
        float t1 = fast_atan2(lenq, dot1);
        float t2 = fast_atan2(lenr, dot2);
        float t3 = FastDiffRots(t1, t2);
        if (b * 0.017453292f < t3) {
            return 0;
        }
    }
    if (a == 0.0f) {
        return 1;
    }
    dot3 = FastVecDot(q, r);
    den = lenr * lenq;
    if (den == 0.0f) {
        return 0;
    }
    if (absolute_float(1.5707964f - FastArcSin(dot3 / den)) < a * 0.017453292f) {
        return 1;
    }
    return 0;
}
